<?php
declare(strict_types=1);namespace Atlas\Platform\Organizations\Onboarding;use Atlas\Platform\Organizations\Domain\OrganizationPolicy;use InvalidArgumentException;final class OrganizationOnboardingService{public function __construct(private OrganizationOnboardingRepository$repository,private OrganizationPolicy$policy){}public function create(string$key,string$name,string$slug,int$userId):array{$key=trim($key);$name=trim($name);$slug=strtolower(trim($slug));if($key===''||strlen($key)>191){throw new InvalidArgumentException('A valid idempotency key is required.');}if(strlen($name)<2||strlen($name)>255){throw new InvalidArgumentException('Organization name must contain 2 to 255 characters.');}if(!$this->policy->isValidSlug($slug)){throw new InvalidArgumentException('Organization slug is invalid.');}if($userId<1){throw new InvalidArgumentException('A valid owner is required.');}$fingerprint=hash('sha256',wp_json_encode([$name,$slug,$userId]));return$this->repository->create($key,$fingerprint,$name,$slug,$userId);}}
